467	    /**
468	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
469	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
470	     * each stored owner's telephone is normalized the same way before comparison so differing
471	     * input formats collapse to the same value.
472	     *
473	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
474	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
475	     *                                     same E.164 telephone
476	     */
477	    /**
478	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
479	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
480	     * the parts may contain whitespace or a second {@code @}.
481	     */
482	    private static final Pattern EMAIL_PATTERN =
483	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
484	
485	    /**
486	     * Disposable email domains that are not accepted for an owner's email. A create whose email
487	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
488	     * rejected. Kept lower-cased to match the normalized email.
489	     */
490	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
491	        "mailinator.com",
492	        "tempmail.com",
493	        "guerrillamail.com");
494	
495	    /**
496	     * Normalizes the submitted email when present: the value is trimmed, required to be a
497	     * syntactically valid address, required not to use a disposable-email domain, and written back
498	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
499	     * left untouched — the field is optional.
500	     *
501	     * @param ownerFieldsDto the submitted owner fields
502	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
503	     *                               valid, or its domain is on the disposable-domain blocklist
504	     */
505	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
506	        String email = ownerFieldsDto.getEmail();
507	        if (email == null) {
508	            return;
509	        }
510	        String trimmed = email.strip();
511	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
512	            throw new InvalidEmailException(email);
513	        }
514	        String normalized = trimmed.toLowerCase(Locale.ROOT);
515	        String domain = normalized.substring(normalized.indexOf('@') + 1);
516	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
517	            throw new InvalidEmailException(email);
518	        }
519	        ownerFieldsDto.setEmail(normalized);
520	    }
