523	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
524	     * date. A registration may be back-dated but never post-dated. The check is made against the
525	     * value as supplied, before any defaulting or business-day roll (see
526	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
527	     * to the server date).
528	     *
529	     * @param ownerFieldsDto the submitted owner fields
530	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
531	     *                                         after the server's current date
532	     */
533	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
534	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
535	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
536	            throw new FutureRegistrationDateException(supplied);
