540	    /**
541	     * Establishes the effective registration date on create and rolls it onto a business day.
542	     * When the client does not supply a {@code registrationDate} it defaults to the server's
543	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
544	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
545	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
546	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
547	     * the membership number's year segment and the daily create-limit).
548	     *
549	     * @param ownerFieldsDto the submitted owner fields
550	     */
551	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
552	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
553	        if (effective == null) {
554	            effective = LocalDate.now();
555	        }
556	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
557	    }
