559	    /**
560	     * Fixed public holidays that the business-day roll skips. A registration date that lands on
561	     * one of these dates is advanced to the next non-holiday business day (see
562	     * {@link #toBusinessDay}).
563	     */
564	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
565	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
566	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
567	        LocalDate.parse("2026-12-28"));
568	
569	    /**
570	     * Rolls a date forward to the next business day: any date that falls on a Saturday, a Sunday
571	     * or a listed public holiday is advanced one day at a time until it lands on a weekday that is
572	     * not a public holiday; any other date is returned unchanged.
573	     *
574	     * @param date the date to adjust
575	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday
576	     *         business day
577	     */
578	    private static LocalDate toBusinessDay(LocalDate date) {
579	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
580	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
581	            || PUBLIC_HOLIDAYS.contains(date)) {
582	            date = date.plusDays(1);
583	        }
584	        return date;
585	    }
