622	    /**
623	     * Assigns the owner's {@code householdId} on create: a stable, deterministic identifier for
624	     * the household, the first 12 hex characters of the SHA-256 digest of the owner's normalized
625	     * {@code lastName} and {@code postcode} (see {@link #householdIdFor}). Because it is derived
626	     * purely from those two fields, every owner sharing a last name and postcode is assigned the
627	     * same value automatically — including one joining an existing household via
628	     * {@code sharesHousehold} — independent of create order.
629	     *
630	     * @param owner the owner being created (with its {@code lastName} and {@code postcode} already set)
631	     */
632	    private void assignHouseholdId(Owner owner) {
633	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
634	    }
