758	    /**
759	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
760	     * {@link #rejectDuplicateIdentity} and {@link #rejectDuplicateHousehold}, so this owner is not
761	     * a hard duplicate. A declared household member (one that opted in via {@code sharesHousehold})
762	     * is never flagged: it is an acknowledged member of the household, not a suspected duplicate,
763	     * so {@code possibleDuplicate} is {@code false}. Otherwise it is a <em>possible</em> duplicate
764	     * when an existing owner shares its {@code lastName} (compared case-insensitively) and its
765	     * {@code postcode} but has a <em>different</em> normalized {@code telephone}:
766	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to that owner's
767	     * id (the earliest such owner by id when several match). Otherwise {@code possibleDuplicate} is
768	     * {@code false} and {@code possibleDuplicateOf} is left unset. The scan is taken over the
769	     * existing owners before this one is persisted.
770	     *
771	     * @param owner the owner being created (with its {@code lastName}, {@code postcode} and
772	     *              already-normalized {@code telephone} set)
773	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
774	     */
775	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
776	        if (declaredHouseholdMember) {
777	            owner.setPossibleDuplicate(false);
778	            owner.setPossibleDuplicateOf(null);
779	            return;
780	        }
781	        String lastName = owner.getLastName();
782	        String postcode = owner.getPostcode();
783	        String telephone = owner.getTelephone();
784	        Integer matchId = null;
785	        if (lastName != null && postcode != null && telephone != null) {
786	            matchId = this.clinicService.findAllOwners().stream()
787	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
788	                .filter(existing -> postcode.equals(existing.getPostcode()))
789	                .filter(existing -> !telephone.equals(existing.getTelephone()))
790	                .map(Owner::getId)
791	                .filter(id -> id != null)
792	                .min(Integer::compareTo)
793	                .orElse(null);
794	        }
795	        owner.setPossibleDuplicate(matchId != null);
796	        owner.setPossibleDuplicateOf(matchId);
797	    }
