820	    /**
821	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
822	     * owner. This single key consolidates what used to be three separate duplicate checks
823	     * (telephone, email and household): the key is
824	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
825	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
826	     * matches an existing owner's. Because the telephone is part of the key, two members of the
827	     * same household (same {@code householdId}) with different telephones have different identity
828	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
829	     * and email have already been normalized by {@link #normalizeTelephone} and
830	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
831	     * input formats collapse to the same value.
832	     *
833	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
834	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
835	     *                                    whole identity key
836	     */
837	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
838	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(),
839	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
840	        boolean duplicate = this.clinicService.findAllOwners().stream()
841	            .filter(owner -> !owner.isDeleted())
842	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getPostcode(),
843	                owner.getTelephone(), owner.getEmail()))
844	            .anyMatch(identityKey::equals);
845	        if (duplicate) {
846	            throw new DuplicateIdentityException(identityKey);
847	        }
848	    }
849	
850	    /**
851	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
852	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
853	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
854	     * absent), and the {@code householdId} is derived from the {@code lastName} and
855	     * {@code postcode} the same way {@link #assignHouseholdId} assigns it (see
856	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
857	     * their whole identities match, regardless of the exact input formats.
858	     *
859	     * @param lastName  the owner's last name
860	     * @param postcode  the owner's postcode
861	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
862	     * @param email     the owner's email, possibly {@code null}
863	     * @return the canonical identity key
864	     */
865	    private static String identityKeyFor(String lastName, String postcode, String telephone, String email) {
866	        String normalizedTelephone = toE164(telephone);
867	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
868	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
869	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, postcode);
870	    }
