920	    /**
921	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
922	     * every internal run of whitespace is collapsed to a single space, and the result is
923	     * lower-cased. A {@code null} value collapses to the empty string.
924	     *
925	     * @param value the value to canonicalize, possibly {@code null}
926	     * @return the collapsed, lower-cased value
927	     */
928	    private static String collapse(String value) {
929	        if (value == null) {
930	            return "";
931	        }
932	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
933	    }
